// Marks untagged page content as artifacts in a PDF content stream.
//
// Chromium's tagged PDF output tags everything that is in the accessibility tree. What it
// leaves untagged is decoration: page backgrounds, rules, borders, and text generated by CSS
// (running headers, footers, page numbers in Paged.js margin boxes). PDF/UA (ISO 14289-1,
// 7.1) requires all content to be either tagged or marked as an artifact, so each untagged
// painting operation is wrapped in `/Artifact BMC … EMC`. Tagged content is left untouched.

const WS = new Set([0x00, 0x09, 0x0a, 0x0c, 0x0d, 0x20]);
const DELIM = new Set([0x28, 0x29, 0x3c, 0x3e, 0x5b, 0x5d, 0x7b, 0x7d, 0x2f, 0x25]);

type Token = { kind: 'op'; value: string; start: number; end: number } | { kind: 'operand'; value: string; start: number; end: number };

/** Splits a content stream into operands and operators, keeping byte offsets. */
function* tokens(src: Uint8Array): Generator<Token> {
  let i = 0;
  const n = src.length;
  const text = (a: number, b: number) => String.fromCharCode(...src.subarray(a, Math.min(b, a + 64)));
  while (i < n) {
    const c = src[i];
    if (WS.has(c)) {
      i++;
      continue;
    }
    if (c === 0x25 /* % */) {
      while (i < n && src[i] !== 0x0a && src[i] !== 0x0d) i++;
      continue;
    }
    const start = i;
    if (c === 0x28 /* ( */) {
      let depth = 0;
      for (; i < n; i++) {
        if (src[i] === 0x5c /* \ */) {
          i++;
          continue;
        }
        if (src[i] === 0x28) depth++;
        else if (src[i] === 0x29 && --depth === 0) {
          i++;
          break;
        }
      }
      yield { kind: 'operand', value: '(string)', start, end: i };
      continue;
    }
    if (c === 0x3c /* < */ && src[i + 1] === 0x3c) {
      // Dictionary: find the matching >>, skipping strings.
      let depth = 0;
      while (i < n) {
        if (src[i] === 0x3c && src[i + 1] === 0x3c) {
          depth++;
          i += 2;
        } else if (src[i] === 0x3e && src[i + 1] === 0x3e) {
          depth--;
          i += 2;
          if (depth === 0) break;
        } else if (src[i] === 0x28) {
          let d = 0;
          for (; i < n; i++) {
            if (src[i] === 0x5c) {
              i++;
              continue;
            }
            if (src[i] === 0x28) d++;
            else if (src[i] === 0x29 && --d === 0) {
              i++;
              break;
            }
          }
        } else i++;
      }
      yield { kind: 'operand', value: text(start, i), start, end: i };
      continue;
    }
    if (c === 0x3c) {
      while (i < n && src[i] !== 0x3e) i++;
      i++;
      yield { kind: 'operand', value: '<hex>', start, end: i };
      continue;
    }
    if (c === 0x5b /* [ */ || c === 0x5d /* ] */ || c === 0x7b || c === 0x7d) {
      i++;
      yield { kind: 'operand', value: String.fromCharCode(c), start, end: i };
      continue;
    }
    if (c === 0x2f /* / */) {
      i++;
      while (i < n && !WS.has(src[i]) && !DELIM.has(src[i])) i++;
      yield { kind: 'operand', value: text(start, i), start, end: i };
      continue;
    }
    while (i < n && !WS.has(src[i]) && !DELIM.has(src[i])) i++;
    if (i === start) {
      i++; // stray delimiter such as ")" or ">"
      continue;
    }
    const word = text(start, i);
    if (/^[+-]?(\d+\.?\d*|\.\d+)$/.test(word) || word === 'true' || word === 'false' || word === 'null') {
      yield { kind: 'operand', value: word, start, end: i };
      continue;
    }
    if (word === 'BI') {
      // Inline image: skip to "EI" preceded by whitespace and followed by whitespace or the end.
      let j = i;
      while (j < n - 1) {
        if (src[j] === 0x45 && src[j + 1] === 0x49 && WS.has(src[j - 1]) && (j + 2 >= n || WS.has(src[j + 2]))) break;
        j++;
      }
      i = Math.min(n, j + 2);
      yield { kind: 'op', value: 'BI', start, end: i };
      continue;
    }
    yield { kind: 'op', value: word, start, end: i };
  }
}

const PATH_START = new Set(['m', 're']);
const PATH_PAINT = new Set(['S', 's', 'f', 'F', 'f*', 'B', 'B*', 'b', 'b*']);
const TEXT_SHOW = new Set(['Tj', 'TJ', "'", '"']);
const OTHER_PAINT = new Set(['Do', 'sh', 'BI']);

export interface ArtifactResult {
  bytes: Uint8Array;
  /** Number of painting operations wrapped as artifacts. */
  wrapped: number;
}

/**
 * Wraps painting operations that are outside tagged (MCID) or artifact marked content.
 * `isTaggedForm(name)` tells which XObjects are forms with tagged content of their own: their
 * Do operators stay unwrapped (an artifact may not contain tagged content), and the caller
 * marks the untagged content inside those forms instead.
 */
export function markUntaggedAsArtifacts(src: Uint8Array, isTaggedForm: (name: string) => boolean = () => false): ArtifactResult {
  const stack: boolean[] = []; // true when the sequence (or an ancestor) is tagged or an artifact
  const covered = () => stack.length > 0 && stack[stack.length - 1];
  const inserts: Array<{ at: number; text: string }> = [];
  let operands: Token[] = [];
  let pathStart = -1;
  let wrapped = 0;
  const wrap = (from: number, to: number) => {
    inserts.push({ at: from, text: '/Artifact BMC\n' }, { at: to, text: '\nEMC' });
    wrapped++;
  };
  for (const t of tokens(src)) {
    if (t.kind === 'operand') {
      operands.push(t);
      continue;
    }
    const opStart = operands.length ? operands[0].start : t.start;
    const op = t.value;
    if (op === 'BMC' || op === 'BDC') {
      const tag = operands[0]?.value ?? '';
      const props = operands[1]?.value ?? '';
      const marks = tag === '/Artifact' || /\/MCID\s/.test(props) || (op === 'BDC' && props.startsWith('/'));
      stack.push(covered() || marks);
    } else if (op === 'EMC') stack.pop();
    else if (PATH_START.has(op)) {
      if (pathStart < 0) pathStart = opStart;
    } else if (PATH_PAINT.has(op)) {
      if (!covered()) wrap(pathStart >= 0 ? pathStart : opStart, t.end);
      pathStart = -1;
    } else if (op === 'n') pathStart = -1;
    else if (op === 'Do' && isTaggedForm(operands[operands.length - 1]?.value.slice(1) ?? '')) {
      // Tagged form: leave it; its own content is marked separately.
    } else if (TEXT_SHOW.has(op) || OTHER_PAINT.has(op)) {
      if (!covered()) wrap(opStart, t.end);
    }
    operands = [];
  }
  if (!inserts.length) return { bytes: src, wrapped: 0 };
  inserts.sort((a, b) => a.at - b.at);
  const enc = new TextEncoder();
  const parts: Uint8Array[] = [];
  let last = 0;
  for (const ins of inserts) {
    parts.push(src.subarray(last, ins.at), enc.encode(ins.text));
    last = ins.at;
  }
  parts.push(src.subarray(last));
  const out = new Uint8Array(parts.reduce((s, p) => s + p.length, 0));
  let o = 0;
  for (const p of parts) {
    out.set(p, o);
    o += p.length;
  }
  return { bytes: out, wrapped };
}
